import * as THREE from 'three';

export type DwarfWarriorClipName = 'idle' | 'walk' | 'run' | 'sleep' | 'sit' | 'attack1' | 'attack2' | 'attack3' | 'mine1' | 'mine2' | 'death';
export type DwarfWarriorState = DwarfWarriorClipName | 'attack' | 'attack_combo';

export const DWARF_CLIP_NAMES: DwarfWarriorClipName[] = [
  'idle', 'walk', 'run', 'sleep', 'sit', 'attack1', 'attack2', 'attack3', 'mine1', 'mine2', 'death'
];

export const DWARF_TOTAL_INDICES = 66105;
export const DWARF_BODY_INDICES = 55161;

export interface DwarfWarriorAssets {
  geometry: THREE.BufferGeometry;
  material: THREE.MeshStandardMaterial;
  parents: Int8Array;
  restTranslations: Float32Array;
  restRotations: Float32Array;
  inverseBindMatrices: Float32Array;
  clips: Record<DwarfWarriorClipName, THREE.AnimationClip>;
}

let cachedPackKey = '';
let cachedAssets: Promise<DwarfWarriorAssets> | null = null;
let cachedSyncPackKey = '';
let cachedSyncAssets: DwarfWarriorAssets | null = null;

function decodeBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

function createPlaceholderCanvas(r: number, g: number, b: number): HTMLCanvasElement | undefined {
  if (typeof document === 'undefined') return undefined;
  const c = document.createElement('canvas');
  c.width = 2;
  c.height = 2;
  const ctx = c.getContext('2d');
  if (ctx) {
    ctx.fillStyle = `rgb(${r},${g},${b})`;
    ctx.fillRect(0, 0, 2, 2);
  }
  return c;
}

function loadTexture(dataUri: string): Promise<THREE.Texture> {
  return new Promise((resolve) => {
    if (typeof Image === 'undefined') {
      const fallback = new THREE.DataTexture(new Uint8Array([165, 115, 75, 255]), 1, 1);
      fallback.colorSpace = THREE.SRGBColorSpace;
      fallback.needsUpdate = true;
      resolve(fallback);
      return;
    }
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => {
      const tex = new THREE.Texture(img);
      tex.flipY = false;
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.needsUpdate = true;
      resolve(tex);
    };
    img.src = dataUri;
  });
}

function loadTextureSync(dataUri: string): THREE.Texture {
  if (typeof Image === 'undefined') {
    const fallback = new THREE.DataTexture(new Uint8Array([165, 115, 75, 255]), 1, 1);
    fallback.flipY = false;
    fallback.colorSpace = THREE.SRGBColorSpace;
    fallback.needsUpdate = true;
    return fallback;
  }
  const placeholder = createPlaceholderCanvas(165, 115, 75);
  const tex = new THREE.Texture(placeholder as TexImageSource | undefined);
  tex.flipY = false;
  tex.colorSpace = THREE.SRGBColorSpace;
  if (placeholder) {
    tex.needsUpdate = true;
  }
  const img = new Image();
  img.crossOrigin = 'anonymous';
  img.onload = () => {
    tex.image = img;
    tex.flipY = false;
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.needsUpdate = true;
  };
  img.src = dataUri;
  return tex;
}

function parseDwarfWarriorPackBuffer(raw: ArrayBuffer, texture: THREE.Texture): DwarfWarriorAssets {
  const NUM_VERTS = 13449;
  const NUM_INDICES = 66105;
  const NUM_JOINTS = 22;
  const NUM_CLIPS = 11;
  const NUM_FRAMES = 20;

  let off = 0;
  const pad4 = () => { off = (off + 3) & ~3; };

  const posI16 = new Int16Array(raw, off, NUM_VERTS * 3);
  off += NUM_VERTS * 3 * 2;
  const positions = new Float32Array(NUM_VERTS * 3);
  for (let i = 0; i < posI16.length; i++) positions[i] = posI16[i] / 8000.0;

  const normalsI8 = new Int8Array(raw, off, NUM_VERTS * 3);
  off += NUM_VERTS * 3;
  pad4();
  const normals = new Float32Array(NUM_VERTS * 3);
  for (let i = 0; i < normalsI8.length; i++) normals[i] = normalsI8[i] / 127.0;

  const uvsU16 = new Uint16Array(raw, off, NUM_VERTS * 2);
  off += NUM_VERTS * 2 * 2;
  pad4();
  const uvs = new Float32Array(NUM_VERTS * 2);
  for (let i = 0; i < uvsU16.length; i++) uvs[i] = uvsU16[i] / 65535.0;

  const skinIndices = new Uint8Array(raw, off, NUM_VERTS * 4);
  off += NUM_VERTS * 4;

  const skinWeights = new Uint8Array(raw, off, NUM_VERTS * 4);
  off += NUM_VERTS * 4;

  const indices = new Uint16Array(raw, off, NUM_INDICES);
  off += NUM_INDICES * 2;
  pad4();

  const parents = new Int8Array(raw, off, NUM_JOINTS);
  off += NUM_JOINTS;
  pad4();

  const restTranslations = new Float32Array(raw, off, NUM_JOINTS * 3);
  off += NUM_JOINTS * 3 * 4;

  const restRotations = new Float32Array(raw, off, NUM_JOINTS * 4);
  off += NUM_JOINTS * 4 * 4;

  const inverseBindMatrices = new Float32Array(raw, off, NUM_JOINTS * 16);
  off += NUM_JOINTS * 16 * 4;

  const clipDurations = new Float32Array(raw, off, 16);
  off += 16 * 4;

  const clipRootTranslations = new Float32Array(raw, off, NUM_CLIPS * NUM_FRAMES * 3);
  off += NUM_CLIPS * NUM_FRAMES * 3 * 4;

  const clipJointQuatsI16 = new Int16Array(raw, off, NUM_CLIPS * NUM_FRAMES * NUM_JOINTS * 4);
  off += NUM_CLIPS * NUM_FRAMES * NUM_JOINTS * 4 * 2;
  const clipWeaponTranslations = (raw.byteLength >= off + NUM_CLIPS * NUM_FRAMES * 3 * 4)
    ? new Float32Array(raw, off, NUM_CLIPS * NUM_FRAMES * 3)
    : new Float32Array(NUM_CLIPS * NUM_FRAMES * 3);

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geometry.setAttribute('normal', new THREE.BufferAttribute(normals, 3));
  geometry.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
  geometry.setAttribute('skinIndex', new THREE.BufferAttribute(skinIndices, 4));
  geometry.setAttribute('skinWeight', new THREE.BufferAttribute(skinWeights, 4, true));
  geometry.setIndex(new THREE.BufferAttribute(indices, 1));
  geometry.computeBoundingSphere();

  const material = new THREE.MeshStandardMaterial({
    map: texture,
    color: 0xffffff,
    roughness: 0.72,
    metalness: 0.03,
    side: THREE.DoubleSide
  });

  const clips = {} as Record<DwarfWarriorClipName, THREE.AnimationClip>;
  for (let c = 0; c < NUM_CLIPS; c++) {
    const name = DWARF_CLIP_NAMES[c];
    const dur = clipDurations[c];
    const times = new Float32Array(NUM_FRAMES);
    for (let f = 0; f < NUM_FRAMES; f++) times[f] = (f / (NUM_FRAMES - 1)) * dur;

    const tracks: THREE.KeyframeTrack[] = [];
    const rootPosValues = new Float32Array(NUM_FRAMES * 3);
    for (let f = 0; f < NUM_FRAMES; f++) {
      const srcIdx = (c * NUM_FRAMES + f) * 3;
      rootPosValues[f * 3 + 0] = clipRootTranslations[srcIdx + 0];
      rootPosValues[f * 3 + 1] = clipRootTranslations[srcIdx + 1];
      rootPosValues[f * 3 + 2] = clipRootTranslations[srcIdx + 2];
    }
    tracks.push(new THREE.VectorKeyframeTrack('J0.position', times, rootPosValues));

    const weapJoint = 14;
    const weapPosValues = new Float32Array(NUM_FRAMES * 3);
    for (let f = 0; f < NUM_FRAMES; f++) {
      const srcIdx = (c * NUM_FRAMES + f) * 3;
      weapPosValues[f * 3 + 0] = restTranslations[weapJoint * 3 + 0] + clipWeaponTranslations[srcIdx + 0];
      weapPosValues[f * 3 + 1] = restTranslations[weapJoint * 3 + 1] + clipWeaponTranslations[srcIdx + 1];
      weapPosValues[f * 3 + 2] = restTranslations[weapJoint * 3 + 2] + clipWeaponTranslations[srcIdx + 2];
    }
    tracks.push(new THREE.VectorKeyframeTrack(`J${weapJoint}.position`, times, weapPosValues));

    for (let j = 0; j < NUM_JOINTS; j++) {
      const qValues = new Float32Array(NUM_FRAMES * 4);
      for (let f = 0; f < NUM_FRAMES; f++) {
        const srcIdx = ((c * NUM_FRAMES + f) * NUM_JOINTS + j) * 4;
        let qx = clipJointQuatsI16[srcIdx + 0] / 32767.0;
        let qy = clipJointQuatsI16[srcIdx + 1] / 32767.0;
        let qz = clipJointQuatsI16[srcIdx + 2] / 32767.0;
        let qw = clipJointQuatsI16[srcIdx + 3] / 32767.0;
        const len = Math.hypot(qx, qy, qz, qw) || 1;
        qx /= len; qy /= len; qz /= len; qw /= len;
        if (f > 0) {
          const prevIdx = (f - 1) * 4;
          const dot = qValues[prevIdx] * qx + qValues[prevIdx + 1] * qy + qValues[prevIdx + 2] * qz + qValues[prevIdx + 3] * qw;
          if (dot < 0) { qx = -qx; qy = -qy; qz = -qz; qw = -qw; }
        }
        qValues[f * 4 + 0] = qx;
        qValues[f * 4 + 1] = qy;
        qValues[f * 4 + 2] = qz;
        qValues[f * 4 + 3] = qw;
      }
      tracks.push(new THREE.QuaternionKeyframeTrack(`J${j}.quaternion`, times, qValues));
    }

    clips[name] = new THREE.AnimationClip(name, dur, tracks);
  }

  return { geometry, material, parents, restTranslations, restRotations, inverseBindMatrices, clips };
}

export async function loadDwarfWarriorAssets(packB64: string, texDataUri: string): Promise<DwarfWarriorAssets> {
  if (cachedAssets && cachedPackKey === packB64) return cachedAssets;
  cachedPackKey = packB64;

  cachedAssets = (async () => {
    const raw = decodeBase64(packB64).buffer as ArrayBuffer;
    const texture = await loadTexture(texDataUri);
    return parseDwarfWarriorPackBuffer(raw, texture);
  })();

  return cachedAssets;
}

export function unpackDwarfWarriorAssetsSync(
  packB64: string = DWARF_PACK_B64,
  texDataUri: string = DWARF_TEX_B64
): DwarfWarriorAssets {
  if (cachedSyncAssets && cachedSyncPackKey === packB64) return cachedSyncAssets;
  cachedSyncPackKey = packB64;
  const raw = decodeBase64(packB64).buffer as ArrayBuffer;
  const texture = loadTextureSync(texDataUri);
  cachedSyncAssets = parseDwarfWarriorPackBuffer(raw, texture);
  return cachedSyncAssets;
}

export interface DwarfWarriorSpawnOptions {
  initialState?: DwarfWarriorState;
  weaponVisible?: boolean;
  tintHex?: number;
  scale?: number;
  castShadow?: boolean;
  receiveShadow?: boolean;
  driveRootMotion?: boolean;
}

export type IDwarfWarriorRig = DwarfWarrior;

export function createReadyDwarfWarrior(options?: DwarfWarriorSpawnOptions): DwarfWarrior {
  const baseAssets = unpackDwarfWarriorAssetsSync();
  const dwarf = new DwarfWarrior({
    ...baseAssets,
    material: baseAssets.material,
  });
  if (options?.driveRootMotion !== undefined) {
    dwarf.driveRootMotion = options.driveRootMotion;
  }
  if (options?.initialState !== undefined) {
    dwarf.setState(options.initialState, 0);
  }
  if (options?.weaponVisible !== undefined) {
    dwarf.setWeaponVisible(options.weaponVisible);
  }
  if (options?.scale !== undefined && options.scale !== 1) {
    dwarf.group.scale.setScalar(options.scale);
  }
  if (options?.castShadow !== undefined) {
    dwarf.skinnedMesh.castShadow = options.castShadow;
  }
  if (options?.receiveShadow !== undefined) {
    dwarf.skinnedMesh.receiveShadow = options.receiveShadow;
  }
  return dwarf;
}

export class DwarfWarrior {
  public readonly group = new THREE.Group();
  public skinnedMesh!: THREE.SkinnedMesh;
  public skeleton!: THREE.Skeleton;
  public bones: THREE.Bone[] = [];
  public weaponNode: THREE.Bone | null = null;
  public mixer!: THREE.AnimationMixer;
  public actions: Partial<Record<DwarfWarriorClipName, THREE.AnimationAction>> = {};

  public state: DwarfWarriorState = 'idle';
  public speed: number = 0;
  public turn: number = 0;
  public timeScale: number = 1.0;
  public weaponVisible: boolean = true;
  public driveRootMotion: boolean = true;

  private restTranslations!: Float32Array;
  private restRotations!: Float32Array;
  private currentAction: THREE.AnimationAction | null = null;
  private comboMode: boolean = false;
  private comboStage: number = 0;
  private comboTimer: number = 0;
  private spineBones: THREE.Bone[] = [];
  private neckHeadBones: THREE.Bone[] = [];
  private readonly _steerQ = new THREE.Quaternion();
  private readonly _axisY = new THREE.Vector3(0, 1, 0);

  constructor(assets: DwarfWarriorAssets) {
    this.buildFromAssets(assets);
  }

  public static async create(packB64: string, texDataUri: string): Promise<DwarfWarrior> {
    const assets = await loadDwarfWarriorAssets(packB64, texDataUri);
    return new DwarfWarrior(assets);
  }

  private buildFromAssets(assets: DwarfWarriorAssets): void {
    this.restTranslations = assets.restTranslations;
    this.restRotations = assets.restRotations;
    const numJoints = assets.parents.length;
    this.bones = new Array(numJoints);
    const boneInverses: THREE.Matrix4[] = new Array(numJoints);

    for (let j = 0; j < numJoints; j++) {
      const bone = new THREE.Bone();
      bone.name = `J${j}`;
      bone.position.set(
        assets.restTranslations[j * 3 + 0],
        assets.restTranslations[j * 3 + 1],
        assets.restTranslations[j * 3 + 2]
      );
      bone.quaternion.set(
        assets.restRotations[j * 4 + 0],
        assets.restRotations[j * 4 + 1],
        assets.restRotations[j * 4 + 2],
        assets.restRotations[j * 4 + 3]
      );
      this.bones[j] = bone;

      const ibm = new THREE.Matrix4();
      ibm.fromArray(assets.inverseBindMatrices, j * 16);
      boneInverses[j] = ibm;
    }

    for (let j = 0; j < numJoints; j++) {
      const p = assets.parents[j];
      if (p >= 0) {
        this.bones[p].add(this.bones[j]);
      }
    }

    this.skeleton = new THREE.Skeleton(this.bones, boneInverses);
    this.skinnedMesh = new THREE.SkinnedMesh(assets.geometry.clone(), assets.material);
    this.skinnedMesh.castShadow = true;
    this.skinnedMesh.receiveShadow = true;
    this.skinnedMesh.frustumCulled = false;

    this.skinnedMesh.add(this.bones[0]);
    this.skinnedMesh.bind(this.skeleton);
    this.group.add(this.skinnedMesh);
    this.weaponNode = this.bones[14] ?? null;

    this.spineBones = [this.bones[1], this.bones[2]];
    this.neckHeadBones = [this.bones[3], this.bones[4]];

    this.mixer = new THREE.AnimationMixer(this.skinnedMesh);
    for (const name of DWARF_CLIP_NAMES) {
      const clip = assets.clips[name];
      if (clip) {
        const action = this.mixer.clipAction(clip);
        if (name === 'death') {
          action.setLoop(THREE.LoopOnce, 1);
          action.clampWhenFinished = true;
        }
        this.actions[name] = action;
      }
    }

    this.setState('idle', 0);
  }

  public resetToRest(): void {
    this.mixer.stopAllAction();
    this.currentAction = null;
    for (let j = 0; j < this.bones.length; j++) {
      this.bones[j].position.set(
        this.restTranslations[j * 3 + 0],
        this.restTranslations[j * 3 + 1],
        this.restTranslations[j * 3 + 2]
      );
      this.bones[j].quaternion.set(
        this.restRotations[j * 4 + 0],
        this.restRotations[j * 4 + 1],
        this.restRotations[j * 4 + 2],
        this.restRotations[j * 4 + 3]
      );
    }
    this.skeleton.update();
  }

  public setNormalizedPhase(stateOrPhase: DwarfWarriorState | number, maybePhase?: number): void {
    let u = 0;
    if (typeof stateOrPhase === 'string') {
      if (this.state !== stateOrPhase || !this.currentAction) {
        this.setState(stateOrPhase, 0);
      }
      u = maybePhase ?? 0;
    } else {
      u = stateOrPhase;
    }
    if (!this.currentAction) return;
    const clip = this.currentAction.getClip();
    if (!clip || clip.duration <= 0) return;
    const clamped = ((u % 1) + 1) % 1;
    this.currentAction.time = clamped * clip.duration;
    this.mixer.update(0);
    if (!this.driveRootMotion && this.bones[0] && this.restTranslations) {
      this.bones[0].position.x = this.restTranslations[0];
      this.bones[0].position.z = this.restTranslations[2];
    }
  }

  public setWeaponVisible(visible: boolean): void {
    this.weaponVisible = visible;
    if (this.skinnedMesh && this.skinnedMesh.geometry) {
      this.skinnedMesh.geometry.setDrawRange(0, visible ? DWARF_TOTAL_INDICES : DWARF_BODY_INDICES);
    }
  }

  private playClipAction(clipName: DwarfWarriorClipName, fadeDuration: number = 0.22): void {
    const nextAction = this.actions[clipName];
    if (!nextAction) return;
    nextAction.reset();
    nextAction.enabled = true;
    nextAction.setEffectiveTimeScale(1);
    nextAction.setEffectiveWeight(1);
    if (this.currentAction && this.currentAction !== nextAction && fadeDuration > 0) {
      this.currentAction.crossFadeTo(nextAction, fadeDuration, true);
      nextAction.play();
    } else {
      if (this.currentAction) this.currentAction.stop();
      nextAction.play();
    }
    this.currentAction = nextAction;
  }

  public setState(nextState: DwarfWarriorState, fadeDuration: number = 0.24): void {
    if (nextState === 'attack' || nextState === 'attack_combo') {
      this.state = nextState;
      this.comboMode = true;
      this.comboStage = 0;
      this.comboTimer = 0;
      this.playClipAction('attack1', fadeDuration);
      return;
    }
    this.comboMode = false;
    const clipName = nextState as DwarfWarriorClipName;
    if (
      this.state === nextState &&
      this.currentAction === this.actions[clipName] &&
      (nextState === 'death' || this.currentAction?.isRunning() || this.currentAction?.paused)
    ) {
      return;
    }
    this.state = nextState;
    this.playClipAction(clipName, fadeDuration);
  }

  public update(dt: number): void {
    let animRate = this.timeScale;
    if (this.state === 'walk' && this.speed > 0.01) {
      animRate *= THREE.MathUtils.clamp(this.speed / 1.8, 0.5, 2.0);
    } else if (this.state === 'run' && this.speed > 0.01) {
      animRate *= THREE.MathUtils.clamp(this.speed / 5.2, 0.5, 2.2);
    }

    if (this.comboMode) {
      const stages: DwarfWarriorClipName[] = ['attack1', 'attack2', 'attack3'];
      const curClip = this.actions[stages[this.comboStage]]?.getClip();
      const endRatio = this.comboStage === 0 ? 0.68 : (this.comboStage === 1 ? 0.65 : 0.84);
      const stageDur = curClip ? Math.max(0.2, curClip.duration * endRatio) : 0.72;
      this.comboTimer += dt * animRate;
      if (this.comboTimer >= stageDur) {
        this.comboTimer = 0;
        this.comboStage = (this.comboStage + 1) % 3;
        const nextName = stages[this.comboStage];
        this.playClipAction(nextName, 0.18);
        const nextAct = this.actions[nextName];
        const nextClip = nextAct?.getClip();
        if (nextAct && nextClip) {
          const startRatio = this.comboStage === 1 ? 0.16 : (this.comboStage === 2 ? 0.12 : 0.08);
          nextAct.time = nextClip.duration * startRatio;
        }
      }
    }

    if (this.state === 'death' && this.currentAction) {
      const clip = this.currentAction.getClip();
      if (clip && clip.duration > 0) {
        const nextTime = this.currentAction.time + dt * animRate;
        if (nextTime >= clip.duration * 0.96) {
          this.currentAction.paused = false;
          this.currentAction.time = clip.duration * 0.99;
          this.mixer.update(0);
        } else {
          this.mixer.update(dt * animRate);
        }
      } else {
        this.mixer.update(dt * animRate);
      }
    } else if (
      (this.state === 'sleep' || this.state === 'sit') &&
      this.currentAction
    ) {
      const clip = this.currentAction.getClip();
      if (clip && clip.duration > 0) {
        const nextTime = this.currentAction.time + dt * animRate;
        if (nextTime >= clip.duration * 0.92) {
          this.comboTimer += dt;
          this.currentAction.time =
            clip.duration * (0.91 + 0.04 * Math.sin(this.comboTimer * 2.0));
          this.mixer.update(0);
        } else {
          this.mixer.update(dt * animRate);
        }
      } else {
        this.mixer.update(dt * animRate);
      }
    } else {
      this.mixer.update(dt * animRate);
    }

    if (!this.driveRootMotion && this.bones[0] && this.restTranslations) {
      this.bones[0].position.x = this.restTranslations[0];
      this.bones[0].position.z = this.restTranslations[2];
    }

    if (Math.abs(this.turn) > 0.001 && this.state !== 'death' && this.state !== 'sleep') {
      const bend = THREE.MathUtils.clamp(this.turn, -1, 1) * 0.12;
      this._steerQ.setFromAxisAngle(this._axisY, bend * 0.55);
      for (let i = 0; i < this.spineBones.length; i++) {
        this.spineBones[i].quaternion.multiply(this._steerQ);
      }
      this._steerQ.setFromAxisAngle(this._axisY, bend * 0.85);
      for (let i = 0; i < this.neckHeadBones.length; i++) {
        this.neckHeadBones[i].quaternion.multiply(this._steerQ);
      }
    }

    if (this.driveRootMotion && this.speed > 0.001 && this.state !== 'death' && this.state !== 'sleep' && this.state !== 'sit') {
      this.group.rotation.y += this.turn * dt * 1.8;
      const forward = new THREE.Vector3(0, 0, 1).applyAxisAngle(this._axisY, this.group.rotation.y);
      this.group.position.addScaledVector(forward, this.speed * dt);
    }
  }

  public dispose(): void {
    this.mixer.stopAllAction();
    this.skinnedMesh.geometry.dispose();
  }
}

export const DWARF_PACK_B64 = "";
export const DWARF_TEX_B64 = "data:image/webp;base64,";
export const DWARF_DEFAULT_WEAPON_VISIBLE = true;
export const DWARF_SAVED_POSE_EDITS = {"clip_0":{"weapon":{"ox":0.023,"oy":0.006,"oz":0,"rx":-86.8,"ry":18,"rz":-155.25}},"clip_1":{"weapon":{"ox":0,"oy":0,"oz":0,"rx":-99.8,"ry":15.2,"rz":-144}},"clip_2":{"weapon":{"ox":0.012,"oy":0.007,"oz":0.004,"rx":91,"ry":171.6,"rz":33.75}},"clip_3":{"weapon":{"ox":0.258,"oy":0.036,"oz":0.227,"rx":16,"ry":70.8,"rz":0}},"clip_4":{"weapon":{"ox":-0.042,"oy":-0.055,"oz":-0.161,"rx":-134.2,"ry":26,"rz":20.25}},"clip_5":{"weapon":{"ox":0.008,"oy":-0.002,"oz":-0.013,"rx":87.6,"ry":-5.2,"rz":-33.75}},"clip_6":{"weapon":{"ox":0.018,"oy":0.003,"oz":0.013,"rx":103,"ry":-3.6,"rz":-20.25}},"clip_7":{"weapon":{"ox":0.02,"oy":0.008,"oz":0.008,"rx":96.8,"ry":-7.2,"rz":-27}},"clip_8":{"weapon":{"ox":0.019,"oy":-0.007,"oz":0.018,"rx":98,"ry":18,"rz":0}},"clip_9":{"weapon":{"ox":0.01,"oy":0.004,"oz":0.006,"rx":100,"ry":20,"rz":2}}};
export async function createCompleteDwarfWarrior(weaponVisible: boolean = DWARF_DEFAULT_WEAPON_VISIBLE): Promise<DwarfWarrior> {
  const model = await DwarfWarrior.create(DWARF_PACK_B64, DWARF_TEX_B64);
  model.setWeaponVisible(weaponVisible);
  return model;
}
